package com.lifeos.app.data.db

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Guards the current Room v7 schema generated by KSP. The database has eleven
 * active entity tables: retained life-tracking tables, reminders, the
 * reintroduced Notes and Capture features, and the permanent Habits tables.
 *
 * These assertions inspect the exported schema, not a duplicated SQL model.
 * Version-to-version migration behavior is separately covered by
 * AppDatabaseMigrationTest using MigrationTestHelper.
 */
class AppDatabaseSchemaTest {

    private fun readSchemaJson(): String {
        val version = "7.json"
        val candidates = listOf(
            File("schemas", "com.lifeos.app.data.db.AppDatabase/$version"),
            File("app", "schemas/com.lifeos.app.data.db.AppDatabase/$version")
        )
        val hit = candidates.firstOrNull { it.exists() && it.isFile }
        return hit?.readText()
            ?: error("Can't find the exported Room v7 schema at app/schemas/com.lifeos.app.data.db.AppDatabase/7.json.")
    }

    private fun schemaJson() = Json.parseToJsonElement(readSchemaJson()).jsonObject

    private fun entityJsonObjects() =
        schemaJson().getValue("database").jsonObject.getValue("entities").jsonArray.map { it.jsonObject }

    private fun createSqlFor(table: String): String =
        entityJsonObjects()
            .firstOrNull { it.getValue("tableName").jsonPrimitive.content == table }
            ?.getValue("createSql")
            ?.jsonPrimitive
            ?.content
            ?: error("Can't find createSql for table '$table' in exported v7 schema")

    private fun columnsOf(createSql: String): Set<String> =
        Regex("`([a-zA-Z_]+)`").findAll(createSql).map { it.groupValues[1] }.toSet()

    private fun tableNames(): Set<String> =
        entityJsonObjects().map { it.getValue("tableName").jsonPrimitive.content }.toSet()

    @Test
    fun schema_isVersionSeven() {
        val version = schemaJson().getValue("database").jsonObject.getValue("version").jsonPrimitive.content.toInt()
        assertEquals(7, version)
    }

    @Test
    fun schema_keepsEveryCurrentEntityTableExactly() {
        assertEquals(
            setOf(
                "tasks",
                "habits",
                "habit_completions",
                "expenses",
                "diary_entries",
                "reminders",
                "notes",
                "note_folders",
                "captures",
                "habit_checklist_items",
                "habit_checklist_checks"
            ),
            tableNames()
        )
    }

    @Test
    fun schemaV7_reintroducesNotesAndCaptures() {
        val tables = tableNames()
        assertTrue("v7 schema must contain Notes", "notes" in tables)
        assertTrue("v7 schema must contain Note folders", "note_folders" in tables)
        assertTrue("v7 schema must contain Captures", "captures" in tables)
    }

    @Test
    fun schemaV7_remindersTableHasFullColumnSet() {
        val columns = columnsOf(createSqlFor("reminders"))
        val expected = setOf(
            "id", "entityType", "entityId", "title", "nextTriggerAtEpochMillis",
            "repeatType", "repeatDaysCsv", "enabled", "soundEnabled", "vibrationEnabled",
            "snoozeMinutes", "snoozeReturnAtEpochMillis", "updatedAt"
        )
        for (column in expected) {
            assertTrue("v7 reminders table must define column '$column' (found: $columns)", column in columns)
        }
    }

    @Test
    fun schemaV7_diaryEntriesKeepsEveryPersistedColumn() {
        val columns = columnsOf(createSqlFor("diary_entries"))
        val expected = setOf(
            "id", "title", "content", "mood", "tagsCsv", "dateEpochDay", "timeMinutes",
            "aiGenerated", "isReviewed", "attachmentsJson", "isFavorite", "createdAt", "updatedAt"
        )
        for (column in expected) {
            assertTrue("v7 diary_entries must define column '$column' (found: $columns)", column in columns)
        }
    }

    @Test
    fun schemaV7_notesAndCapturesKeepTheirCurrentFields() {
        val noteColumns = columnsOf(createSqlFor("notes"))
        val expectedNotes = setOf(
            "id", "title", "content", "contentJson", "tagsCsv", "folderId",
            "isPinned", "isFavorite", "isArchived", "isTrashed", "trashedAt",
            "createdAt", "updatedAt"
        )
        for (column in expectedNotes) {
            assertTrue("v7 notes table must define column '$column' (found: $noteColumns)", column in noteColumns)
        }

        val captureColumns = columnsOf(createSqlFor("captures"))
        val expectedCaptures = setOf(
            "id", "type", "text", "filePath", "mimeType", "durationMillis",
            "latitude", "longitude", "placeLabel", "moodKey", "tagsCsv",
            "isFavorite", "createdAt"
        )
        for (column in expectedCaptures) {
            assertTrue("v7 captures table must define column '$column' (found: $captureColumns)", column in captureColumns)
        }
    }

    @Test
    fun schemaV7_noteFoldersKeepTheirCurrentFields() {
        val columns = columnsOf(createSqlFor("note_folders"))
        for (column in setOf("id", "name", "position", "createdAt")) {
            assertTrue("v7 note_folders table must define column '$column' (found: $columns)", column in columns)
        }
    }

    @Test
    fun schemaV7_habitsCarriesEveryPermanentHabitColumn() {
        val columns = columnsOf(createSqlFor("habits"))
        val expected = setOf(
            "id", "name", "icon", "category", "frequency", "customDaysCsv",
            "goalCount", "reminderEpochMillis", "startDateEpochDay",
            "isArchived", "createdAt", "updatedAt",
            // v7 additions
            "description", "colorArgb", "habitType", "trackingMode",
            "scheduleType", "daysOfWeekCsv", "daysOfMonthCsv",
            "timesPerPeriod", "showOnTimeline"
        )
        for (column in expected) {
            assertTrue("v7 habits table must define column '$column' (found: $columns)", column in columns)
        }
    }

    @Test
    fun schemaV7_completionsRecordExplicitOutcomeAndTargetSnapshot() {
        val columns = columnsOf(createSqlFor("habit_completions"))
        for (column in setOf("habitId", "dateEpochDay", "progressCount", "completedAtEpochMillis", "outcome", "targetCount")) {
            assertTrue("v7 habit_completions must define column '$column' (found: $columns)", column in columns)
        }
    }

    @Test
    fun schemaV7_checklistTablesKeepTheirTemplateAndCheckShape() {
        val itemColumns = columnsOf(createSqlFor("habit_checklist_items"))
        for (column in setOf("id", "habitId", "label", "position", "isArchived", "createdAt")) {
            assertTrue("v7 habit_checklist_items must define column '$column' (found: $itemColumns)", column in itemColumns)
        }

        val checkColumns = columnsOf(createSqlFor("habit_checklist_checks"))
        for (column in setOf("itemId", "habitId", "dateEpochDay", "isChecked", "checkedAtEpochMillis", "labelSnapshot")) {
            assertTrue("v7 habit_checklist_checks must define column '$column' (found: $checkColumns)", column in checkColumns)
        }
    }
}
